import{_ as a,o as i,c as s,k as t}from"./chunks/framework.ystBm8og.js";const u=JSON.parse('{"title":"Releasing","description":"","frontmatter":{},"headers":[],"relativePath":"develop/releasing.md","filePath":"develop/releasing.md","lastUpdated":1785751237000}'),o={name:"develop/releasing.md"};function l(r,e,d,n,c,h){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="releasing" tabindex="-1">Releasing <a class="header-anchor" href="#releasing" aria-label="Permalink to &quot;Releasing&quot;">​</a></h1><p>How installers are built and published for <a href="https://github.com/nikhilakki/pomodoro" target="_blank" rel="noreferrer">nikhilakki/pomodoro</a>.</p><h2 id="ci-matrix" tabindex="-1">CI matrix <a class="header-anchor" href="#ci-matrix" aria-label="Permalink to &quot;CI matrix&quot;">​</a></h2><p>Workflow: <a href="https://github.com/nikhilakki/pomodoro/blob/main/.github/workflows/release.yml" target="_blank" rel="noreferrer"><code>.github/workflows/release.yml</code></a></p><table tabindex="0"><thead><tr><th>Runner</th><th>Target</th></tr></thead><tbody><tr><td><code>macos-latest</code></td><td><code>aarch64-apple-darwin</code></td></tr><tr><td><code>macos-latest</code></td><td><code>x86_64-apple-darwin</code></td></tr><tr><td><code>windows-latest</code></td><td><code>x86_64-pc-windows-msvc</code></td></tr><tr><td><code>windows-11-arm</code></td><td><code>aarch64-pc-windows-msvc</code></td></tr><tr><td><code>ubuntu-22.04</code></td><td><code>x86_64-unknown-linux-gnu</code></td></tr><tr><td><code>ubuntu-22.04-arm</code></td><td><code>aarch64-unknown-linux-gnu</code></td></tr></tbody></table><p>Uses <a href="https://github.com/tauri-apps/tauri-action" target="_blank" rel="noreferrer"><code>tauri-apps/tauri-action</code></a> to build and attach artifacts.</p><h3 id="triggers" tabindex="-1">Triggers <a class="header-anchor" href="#triggers" aria-label="Permalink to &quot;Triggers&quot;">​</a></h3><ul><li>Push of a version tag matching <code>v*</code></li><li>Manual <strong>Actions → Release → Run workflow</strong></li></ul><h2 id="cut-a-release" tabindex="-1">Cut a release <a class="header-anchor" href="#cut-a-release" aria-label="Permalink to &quot;Cut a release&quot;">​</a></h2><ol><li>Bump version in all three places: <ul><li><code>package.json</code></li><li><code>src-tauri/tauri.conf.json</code></li><li><code>src-tauri/Cargo.toml</code> (refresh <code>Cargo.lock</code> if needed)</li></ul></li><li>Commit on <code>main</code> and push.</li><li>Tag and push:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.2.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;v0.2.0&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.2.0</span></span></code></pre></div><ol start="4"><li>Wait for the six matrix jobs. Review the GitHub Release draft/assets.</li><li>Publish the release if the workflow left it as a draft (<code>releaseDraft: true</code> may create drafts; consolidate assets if parallel jobs race).</li></ol><p>Users download from <a href="https://github.com/nikhilakki/pomodoro/releases" target="_blank" rel="noreferrer">Releases</a>.</p><h2 id="code-signing-optional" tabindex="-1">Code signing (optional) <a class="header-anchor" href="#code-signing-optional" aria-label="Permalink to &quot;Code signing (optional)&quot;">​</a></h2><p>Default pipeline only needs <code>GITHUB_TOKEN</code> with <code>contents: write</code>.</p><h3 id="macos-seamless-open" tabindex="-1">macOS (seamless open) <a class="header-anchor" href="#macos-seamless-open" aria-label="Permalink to &quot;macOS (seamless open)&quot;">​</a></h3><p>Configure secrets for signing + notarization so users avoid the <code>xattr</code> Gatekeeper workaround:</p><ul><li><code>APPLE_CERTIFICATE</code></li><li><code>APPLE_CERTIFICATE_PASSWORD</code></li><li><code>APPLE_SIGNING_IDENTITY</code></li><li><code>APPLE_ID</code></li><li><code>APPLE_PASSWORD</code></li><li><code>APPLE_TEAM_ID</code></li></ul><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><p>Optional certificate secrets (e.g. <code>WINDOWS_CERTIFICATE</code>) reduce SmartScreen friction.</p><h2 id="local-release-build" tabindex="-1">Local release build <a class="header-anchor" href="#local-release-build" aria-label="Permalink to &quot;Local release build&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tauri</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>See <a href="/develop/setup">Setup</a> for prerequisites and output paths.</p><h2 id="docs-site-releases" tabindex="-1">Docs site releases <a class="header-anchor" href="#docs-site-releases" aria-label="Permalink to &quot;Docs site releases&quot;">​</a></h2><p>This documentation site (<code>pomodoro-docs</code>) deploys independently via GitHub Actions on push to <code>main</code>. It does not version-lock to app tags; update <a href="/changelog">Changelog</a> when documenting app releases.</p>`,25)])])}const k=a(o,[["render",l]]);export{u as __pageData,k as default};
